namespace sv_96f87b678dc4464d8b52fecd0591f7f0.Client.Models;

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public sealed record StatusUpdate(
    DateTimeOffset Timestamp,
    string Status,
    string Location);

using sv_96f87b678dc4464d8b52fecd0591f7f0.Client.Models;

namespace sv_96f87b678dc4464d8b52fecd0591f7f0.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_96f87b678dc4464d8b52fecd0591f7f0.Client.Models;
using sv_96f87b678dc4464d8b52fecd0591f7f0.Client.Services;

namespace sv_96f87b678dc4464d8b52fecd0591f7f0.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-1001"] = new Shipment(
            "TRK-1001",
            "In Transit",
            "Chicago, IL",
            new DateTimeOffset(2026, 7, 5, 17, 0, 0, TimeSpan.Zero),
            [
                new StatusUpdate(new DateTimeOffset(2026, 6, 28, 9, 0, 0, TimeSpan.Zero), "Picked Up", "New York, NY"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 29, 14, 30, 0, TimeSpan.Zero), "In Transit", "Philadelphia, PA"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 30, 18, 15, 0, TimeSpan.Zero), "In Transit", "Chicago, IL"),
            ]),

        ["TRK-1002"] = new Shipment(
            "TRK-1002",
            "Delivered",
            "San Francisco, CA",
            new DateTimeOffset(2026, 6, 30, 12, 0, 0, TimeSpan.Zero),
            [
                new StatusUpdate(new DateTimeOffset(2026, 6, 26, 8, 0, 0, TimeSpan.Zero), "Picked Up", "Seattle, WA"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 27, 11, 0, 0, TimeSpan.Zero), "In Transit", "Portland, OR"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 28, 16, 45, 0, TimeSpan.Zero), "Out for Delivery", "San Francisco, CA"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 28, 18, 20, 0, TimeSpan.Zero), "Delivered", "San Francisco, CA"),
            ]),

        ["TRK-1003"] = new Shipment(
            "TRK-1003",
            "Processing",
            "Dallas, TX",
            new DateTimeOffset(2026, 7, 8, 15, 0, 0, TimeSpan.Zero),
            [
                new StatusUpdate(new DateTimeOffset(2026, 7, 1, 7, 0, 0, TimeSpan.Zero), "Label Created", "Dallas, TX"),
            ]),
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_96f87b678dc4464d8b52fecd0591f7f0.Client.Models
@using sv_96f87b678dc4464d8b52fecd0591f7f0.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

@if (_isLoading)
{
    <div class="loading-placeholder">
        <p>Loading shipment <strong>@TrackingNumber</strong>…</p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger">
        <p>@_errorMessage</p>
        <button class="btn btn-primary" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="alert alert-warning">
        <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
    </div>
}
else
{
    <h3>Shipment @_shipment.TrackingNumber</h3>
    <dl>
        <dt>Status</dt>
        <dd>@_shipment.Status</dd>
        <dt>Location</dt>
        <dd>@_shipment.Location</dd>
        <dt>Estimated Delivery</dt>
        <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
    </dl>

    <h4>Status History</h4>
    <table class="table">
        <thead>
            <tr>
                <th>Time</th>
                <th>Status</th>
                <th>Location</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var update in _shipment.StatusUpdates)
            {
                <tr>
                    <td>@update.Timestamp.ToString("g")</td>
                    <td>@update.Status</td>
                    <td>@update.Location</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private Shipment? _shipment;
    private bool _isLoading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request before starting a new one.
        CancelPendingRequest();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _shipment = null;
        _errorMessage = null;
        _isLoading = true;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Request was intentionally cancelled (navigation or disposal). Do nothing.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    private void CancelPendingRequest()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        CancelPendingRequest();
    }
}

